%% from 
% since only one q-damingwinding, i_q only with Tq''
idx1 = data(:,1) > 0.10; 
t_raw = data(idx1,1)-0.10; % Time
i_raw = data(idx1,2); % Current
[i_upper, i_lower] = envelope(i_raw, 100, 'peaks'); 
% i_q(t) envelope of (RMS) Stator
plot(t_raw, i_upper);
hold on;
plot(t_raw,i_lower);
plot(t_raw,i_raw);
idy = abs((i_upper + i_lower))/2;
plot(t_raw,idy);
%% 2. Extrapolation of i_q to switchingtime at t = 0
idx_fit = (t_raw > 0.001) & (t_raw < 0.04);
p_q = polyfit(t_raw(idx_fit), log(abs(idy(idx_fit))), 1);
Tq_pp_calc = -1 / p_q(1);
%% 4. Output
fprintf('=== Result of the computation ===\n');
fprintf('Subtransient time constant tq'''' :    %.4f p.u.\n', Tq_pp_calc);
%% 5. Plot of the extrapolation line for q-Axes
figure('Color', 'w');
semilogy(t_raw, idy / In, 'k.', 'DisplayName', 'Extracted i_q');
hold on;
t_plot = linspace(0, 0.06, 100);
semilogy(t_plot, exp(p_q(1)*t_plot + p_q(2)) / In, 'r-', 'LineWidth', 2, ...
    'DisplayName', 'Subtransient q-linearline');
grid on; ax = gca; ax.GridLineStyle = ':';
xlim([0 0.06]);
legend('Location', 'NE');